@Component("carePlan-handler")
@ProcessingGroup("carePlan-processing-group")
public class CarePlanEventHandler {
	
	// core constructor
	CarePlanEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateCarePlanEvent
     */
    @EventHandler
    public void handle( CreateCarePlanEvent event) {
        entityManager.persist(new CarePlan(event.getCarePlanId(), event.getPlanNumber(), event.getGoalSummary(), event.getPatient(), event.getEncounters(), event.getTasks(), event.getCareTeam(), event.getStatus()));
    }

    /*
     * @param	event UpdateCarePlanEvent
     */
    @EventHandler
    public CarePlan handle( UpdateCarePlanEvent event) {
    	entityManager.merge(new CarePlan(event.getCarePlanId(), event.getPlanNumber(), event.getGoalSummary(), event.getPatient(), event.getEncounters(), event.getTasks(), event.getCareTeam(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteCarePlanEvent
     */
    @EventHandler
    public void on( DeleteCarePlanEvent event) {
    	CarePlan entity = new CarePlan();
   
    	// ------------------------------------------
    	// apply the CarePlanId
    	// ------------------------------------------
    	entity.setCarePlanId( event.getCarePlanId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final CarePlanRepository carePlanEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(CarePlanEventHandler.class.getName());

}
